target.css:
:root {
  --card-bg: #1e1e2e;
  --card-border: #2e2e45;
  --header-bg: #16162a;
  --avatar-bg: #7c5cbf;
  --avatar-text: #ffffff;
  --name-color: #e8e8f8;
  --title-color: #9090b8;
  --badge-bg: #7c5cbf;
  --badge-text: #f0eaff;
  --divider-color: #2e2e45;
  --skill-label: #c0c0d8;
  --skill-bar-bg: #2e2e45;
  --fill-js: #f0c040;
  --fill-ts: #4080e0;
  --fill-react: #40c8e0;
  --fill-node: #60c060;
  --skill-pct: #9090b8;
  --stat-value: #e8e8f8;
  --stat-label: #6060a0;
  --stat-border: #2e2e45;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.card {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  width: 480px;
  padding: 20px;
  box-sizing: border-box;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 14px;
  background-color: var(--header-bg);
  border-radius: 12px;
  padding: 14px;
}

.avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background-color: var(--avatar-bg);
  color: var(--avatar-text);
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.header-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
}

.name {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--name-color);
  line-height: 1.2;
}

.title {
  font-size: 13px;
  color: var(--title-color);
  font-weight: 400;
}

.level-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
  flex-shrink: 0;
}

.divider {
  height: 1px;
  background-color: var(--divider-color);
  margin: 16px 0;
}

.skills-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.skill-item {
  display: flex;
  align-items: center;
  gap: 10px;
}

.skill-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--skill-label);
  width: 88px;
  flex-shrink: 0;
}

.skill-bar {
  flex: 1;
  height: 8px;
  background-color: var(--skill-bar-bg);
  border-radius: 4px;
  overflow: hidden;
}

.skill-fill {
  height: 100%;
  border-radius: 4px;
}

.fill-js {
  width: 92%;
  background-color: var(--fill-js);
}

.fill-ts {
  width: 85%;
  background-color: var(--fill-ts);
}

.fill-react {
  width: 88%;
  background-color: var(--fill-react);
}

.fill-node {
  width: 79%;
  background-color: var(--fill-node);
}

.skill-pct {
  font-size: 12px;
  color: var(--skill-pct);
  width: 32px;
  text-align: right;
  flex-shrink: 0;
}

.stats-row {
  display: flex;
  gap: 8px;
}

.stat {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 6px;
  border: 1px solid var(--stat-border);
  border-radius: 10px;
}

.stat-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--stat-value);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--stat-label);
  font-weight: 400;
}

